<?php
require_once(__DIR__ . '/../../config.php'); require_login();
$context=context_system::instance(); require_capability('local/kbacorporate:manageimplementationaudits',$context);
$companyid=required_param('companyid',PARAM_INT); $frameworkid=required_param('frameworkid',PARAM_INT); $toolid=optional_param('toolid',0,PARAM_INT); $competencyid=optional_param('competencyid',0,PARAM_INT); $query=trim(optional_param('q','',PARAM_TEXT));
$company=\local_kbacorporate\local\access::require_full_company_access($companyid,$USER->id); $framework=$DB->get_record('competency_framework',['id'=>$frameworkid],'*',MUST_EXIST);
$tools=$DB->get_records_select('local_kbacorp_bms_tool','companyid IN (0,:companyid)',['companyid'=>$companyid],'code ASC'); $params=['companyid'=>$companyid]; $where='t.companyid IN (0,:companyid) AND c.active=1';
if($toolid){$where.=' AND t.id=:toolid';$params['toolid']=$toolid;} if($competencyid){$where.=' AND EXISTS (SELECT 1 FROM {local_kbacorp_bms_comp} bx WHERE bx.criterionid=c.id AND bx.competencyid=:competencyid)';$params['competencyid']=$competencyid;} if($query!==''){$where.=' AND ('.$DB->sql_like('c.name',':q1',false).' OR '.$DB->sql_like('c.code',':q2',false).' OR '.$DB->sql_like('t.name',':q3',false).')';$params['q1']='%'.$query.'%';$params['q2']='%'.$query.'%';$params['q3']='%'.$query.'%';}
$sql="SELECT c.id,c.toolid,c.code,c.name,c.sectionname,t.code AS toolcode,t.name AS toolname,t.companyid AS toolcompanyid FROM {local_kbacorp_bms_crit} c JOIN {local_kbacorp_bms_tool} t ON t.id=c.toolid WHERE {$where} ORDER BY t.code ASC,c.sortorder ASC,c.code ASC"; $records=$DB->get_records_sql($sql,$params);
$PAGE->set_context($context); $PAGE->set_url(new moodle_url('/local/kbacorporate/framework_mappings.php',['companyid'=>$companyid,'frameworkid'=>$frameworkid,'toolid'=>$toolid,'competencyid'=>$competencyid,'q'=>$query])); $PAGE->set_pagelayout('admin'); $PAGE->set_title(get_string('bmsframeworkmappings','local_kbacorporate')); $PAGE->set_heading(format_string($company->name));
echo $OUTPUT->header(); echo local_kbacorporate_implementation_navigation($companyid,'framework'); echo html_writer::div(html_writer::link(new moodle_url('/local/kbacorporate/framework.php',['companyid'=>$companyid,'frameworkid'=>$frameworkid]),'← '.get_string('bmsframeworkmanager','local_kbacorporate')),'kbacorp-backlink'); echo $OUTPUT->heading(get_string('bmsframeworkmappings','local_kbacorporate'),2); echo html_writer::tag('p',get_string('bmsframeworkmappingsdesc','local_kbacorporate'),['class'=>'kbacorp-pagelead']);
echo html_writer::start_tag('form',['method'=>'get','class'=>'kbacorp-bms-library-filters']); echo html_writer::empty_tag('input',['type'=>'hidden','name'=>'companyid','value'=>$companyid]); echo html_writer::empty_tag('input',['type'=>'hidden','name'=>'frameworkid','value'=>$frameworkid]); echo html_writer::empty_tag('input',['type'=>'search','name'=>'q','value'=>$query,'placeholder'=>get_string('bmsframeworksearchcriteria','local_kbacorporate'),'class'=>'form-control']); $tooloptions=[0=>get_string('allbmstools','local_kbacorporate')]; foreach($tools as $tool){$tooloptions[(int)$tool->id]=s($tool->code).' — '.format_string($tool->name);} echo html_writer::select($tooloptions,'toolid',$toolid,false,['class'=>'custom-select']); echo html_writer::tag('button',get_string('applyfilter','local_kbacorporate'),['type'=>'submit','class'=>'btn btn-primary']); echo html_writer::end_tag('form');
$table=new html_table(); $table->attributes['class']='generaltable kbacorp-report'; $table->head=[get_string('bmstoolcode','local_kbacorporate'),get_string('bmscriterioncode','local_kbacorporate'),get_string('bmscriterionname','local_kbacorporate'),get_string('bmsframeworklinkedcompetencies','local_kbacorporate'),get_string('actions')];
foreach($records as $record){$maps=\local_kbacorporate\local\implementation_audits::get_criterion_competencies((int)$record->id);$chips=[];foreach($maps as $map){if((int)$map->competencyframeworkid!==$frameworkid)continue;$code=$map->idnumber?:('#'.$map->competencyid);$chips[]=html_writer::span(s($code).' — '.format_string($map->shortname).' · L'.(int)$map->targetlevel.' · '.s($map->priority).($map->required?' · '.get_string('required'):''),'badge badge-light mr-1 mb-1');}$mappinghtml=$chips?implode(' ',$chips):html_writer::span(get_string('bmsframeworkunmapped','local_kbacorporate'),'text-muted');$editurl=new moodle_url('/local/kbacorporate/bms_competencies.php',['companyid'=>$companyid,'toolid'=>$record->toolid,'criterionid'=>$record->id]);$table->data[]=[s($record->toolcode),s($record->code),format_string($record->name),$mappinghtml,html_writer::link($editurl,get_string('bmsframeworkeditmapping','local_kbacorporate'))];}
echo html_writer::div(html_writer::table($table),'kbacorp-table-scroll'); echo $OUTPUT->footer();
